// C++ wrapper around the acados solver generated by scripts/export_c_code.py; same
// reference handling and warm start as qnmpc.nmpc.NMPC (checked in test/test_solver.cpp).
#pragma once

#include "quadrotor_nmpc_ros/quad_model.hpp"

namespace quadrotor_nmpc
{

struct SolveResult
{
  Thrusts u{};
  double solve_time_ms = 0;
  int status = 0;
};

class NmpcSolver
{
public:
  explicit NmpcSolver(Figure8 traj);
  ~NmpcSolver();
  NmpcSolver(const NmpcSolver &) = delete;
  NmpcSolver & operator=(const NmpcSolver &) = delete;

  // per-rotor maximum thrust the controller may use (N); no rebuild needed
  void set_thrust_limits(const Thrusts & T_max);
  const Thrusts & thrust_limits() const {return T_max_;}
  void set_trajectory(const Figure8 & traj) {traj_ = traj; initialized_ = false;}

  // one control step at time t from the measured state (real-time iteration)
  SolveResult step(double t, const State & x0);

private:
  void set_reference(double t, const State & x0, State * X, Thrusts * U);
  void set_x0(const State & x0);

  void * capsule_ = nullptr;
  Figure8 traj_;
  Thrusts T_max_{};
  bool initialized_ = false;
};

}  // namespace quadrotor_nmpc
